const CACHE_NAME = 'quran-word-by-word-v4.1.7';const CORE_URLS=[ './','./index.html','./styles.min.css','./script.min.js','./compression-utils.min.js','./enhanced-data-loader.min.js','./migration-patch.min.js','./manifest.json','./data/surah_name.json','./data/juz_data.json','./data/quran_pages.json' ];const CDN_URLS=[ 'https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Scheherazade+New:wght@400;700&family=Lateef:wght@400&family=Reem+Kufi:wght@400;700&family=Noto+Naskh+Arabic:wght@400;500;600;700&family=Harmattan:wght@400;700&family=Alkalami&family=Markazi+Text:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&family=Noto+Serif+Bengali:wght@400;700&family=Noto+Sans+Bengali:wght@400;700&display=swap','https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css','https://cdnjs.cloudflare.com/ajax/libs/pako/2.1.0/pako.min.js' ];self.addEventListener('install',(event)=>{console.log('Service Worker: Installing...');event.waitUntil(caches.open(CACHE_NAME) .then(async(cache)=>{console.log('Service Worker: Caching core files...');await cache.addAll(CORE_URLS);console.log('Service Worker: Core files cached successfully');for(const url of CDN_URLS){try{await cache.add(new Request(url,{mode: 'cors'}));console.log('Service Worker: Cached CDN:',url.substring(0,60)+'...');} catch(e){console.warn('Service Worker: Optional CDN cache failed:',url.substring(0,60));}}}) .catch((error)=>{console.error('Service Worker: Core cache failed:',error);}));self.skipWaiting();});self.addEventListener('activate',(event)=>{console.log('Service Worker: Activating...');event.waitUntil(caches.keys().then((cacheNames)=>{return Promise.all(cacheNames .filter((name)=>name!==CACHE_NAME) .map((name)=>{console.log('Service Worker: Deleting old cache:',name);return caches.delete(name);}));}));self.clients.claim();});self.addEventListener('fetch',(event)=>{if(event.request.method!=='GET') return;if(!event.request.url.startsWith('http')) return;const url=new URL(event.request.url);const isDataFile=url.pathname.includes('/data/');const isSameOrigin=url.origin===self.location.origin;event.respondWith(caches.match(event.request).then((cached)=>{const fetchPromise=fetch(event.request.clone()) .then((response)=>{if(response&&response.status===200){const responseToCache=response.clone();caches.open(CACHE_NAME).then((cache)=>{cache.put(event.request,responseToCache);});} return response;}) .catch(()=>{if(cached) return cached;if(event.request.destination==='document'){return caches.match('./')||caches.match('./index.html');} return new Response('Offline content not available',{status: 503,statusText: 'Service Unavailable',headers: new Headers({'Content-Type': 'text/plain'})});});if(isDataFile){return fetchPromise;} return cached||fetchPromise;}));});self.addEventListener('sync',(event)=>{console.log('Service Worker: Background sync triggered');if(event.tag==='background-sync-data'){event.waitUntil(caches.open(CACHE_NAME) .then((cache)=>{return fetch('./data/surah_name.json') .then(response=>{if(response.ok){cache.put('./data/surah_name.json',response.clone());} return response;});}) .catch((error)=>{console.error('Service Worker: Background sync failed:',error);}));}});self.addEventListener('push',(event)=>{const options={body: event.data ? event.data.text() : 'New content available!',icon: './favicon/android-chrome-192x192.png',badge: './favicon/android-chrome-192x192.png',vibrate: [200,100,200],tag: 'quran-notification',actions: [{action: 'open',title: 'Open App'},{action: 'close',title: 'Close'} ]};event.waitUntil(self.registration.showNotification('Al-Quran Word by Word',options));});self.addEventListener('notificationclick',(event)=>{event.notification.close();if(event.action==='open'||!event.action){event.waitUntil(clients.openWindow('./'));}});self.addEventListener('message',(event)=>{if(event.data&&event.data.type==='SKIP_WAITING'){self.skipWaiting();} if(event.data&&event.data.type==='GET_VERSION'){event.ports[0].postMessage({version: CACHE_NAME});}});self.addEventListener('periodicsync',(event)=>{if(event.tag==='daily-data-sync'){event.waitUntil(caches.open(CACHE_NAME) .then((cache)=>{return cache.add('./data/surah_name.json');}) .catch((error)=>{console.error('Service Worker: Periodic sync failed:',error);}));}});console.log('Service Worker: Script loaded successfully');